contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public payable {
        bool revertedBefore;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBefore = true; } else { revertedBefore = false; }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfter;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedAfter = true; } else { revertedAfter = false; }

        assert(!revertedBefore && revertedAfter);
    }

    receive() external payable {}
}

